import heapq

def shortest_path(edges, start, end):
    """
    Finds the shortest path between a start and end node in a weighted directed graph.

    Parameters:
    - edges: List of tuples representing (from_node, to_node, weight)
    - start: The starting node
    - end: The target node

    Returns:
    - (distance, path): A tuple containing the total distance and a list of nodes 
                        representing the path. Returns (0, [start]) if start == end,
                        and (None, None) if no path exists.
    """
    # Check for negative edge weights
    for u, v, w in edges:
        if w < 0:
            raise ValueError("Edge weights must be non-negative.")

    # Handle case where start and end are the same
    if start == end:
        return (0, [start])

    # Build the adjacency list: graph[u] = [(v, weight), ...]
    graph = {}
    nodes = set()
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))
        nodes.add(u)
        nodes.add(v)

    # If start or end nodes aren't in the graph at all
    if start not in nodes or end not in nodes:
        return (None, None)

    # Priority queue stores tuples of (current_distance, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Dictionary to keep track of the shortest distance found to each node
    distances = {start: 0}

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # If we reached the destination, return the result
        if current_node == end:
            return (current_distance, path)

        # If a shorter path to this node has already been found, skip
        if current_distance > distances.get(current_node, float('inf')):
            continue

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                # If we found a shorter path to the neighbor, update and push to queue
                if distance < distances.get(neighbor, float('inf')):
                    distances[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor, path + [neighbor]))

    # If the priority queue is empty and we haven't reached 'end', no path exists
    return (None, None)
